use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode a string for use as a query-parameter value (RFC 3986
/// unreserved characters pass through; everything else is %XX-encoded).
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn render_entry(out: &mut String, e: &ItemVerdict) {
    out.push_str("- [");
    out.push_str(importance_label(e.importance));
    out.push_str(" / ");
    out.push_str(category_label(e.category));
    out.push_str("] ");
    out.push_str(e.title.trim());
    if !e.feed.is_empty() {
        out.push_str(" (");
        out.push_str(e.feed.trim());
        out.push(')');
    }
    out.push('\n');
    if !e.link.is_empty() {
        out.push_str("  ");
        out.push_str(e.link.trim());
        out.push('\n');
    }
    let summary = e.summary.trim();
    if !summary.is_empty() {
        out.push_str("  ");
        out.push_str(summary);
        out.push('\n');
    }
}

fn render_digest(d: &crate::Digest) -> String {
    let mut msg = String::new();
    msg.push_str("Digest for ");
    msg.push_str(&d.date);
    msg.push_str("\n\n");

    let overview = d.overview.trim();
    if !overview.is_empty() {
        msg.push_str(overview);
        msg.push_str("\n\n");
    }

    let kept: Vec<&ItemVerdict> = d.entries.iter().filter(|e| e.kept).collect();
    if kept.is_empty() {
        msg.push_str("No items made the digest today.\n");
    } else {
        // Must-read first, then worth-a-look, then anything else; stable within a rank.
        for rank in [Importance::MustRead, Importance::WorthALook, Importance::Skip] {
            for e in kept.iter().filter(|e| e.importance == rank) {
                render_entry(&mut msg, e);
            }
        }
    }

    msg.push_str("\n");
    msg.push_str(&d.considered.len().to_string());
    msg.push_str(" items considered.\n");
    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment lookup (approved grant extension). The digest's free text
        // is its overview. The result is fetched but deliberately not used, so
        // the node's output is unchanged; a transport failure is tolerated.
        let url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&composed.overview));
        let _enrichment: Result<String, String> = http_client::fetch(&url);

        let message = render_digest(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

Notes:
- `Digest` has no `text` field, so the enrichment query uses `overview` as "the input's text", percent-encoded. If you meant a different field, change that one line.
- I used `fetch` rather than `get`. A failed enrichment request comes back as a value and is ignored, so it can't fail the run.
- The response is thrown away, so the output is the same as before. The `ensures present(published)` contract always holds because `published` is a `bool` that is always set.
- The graph still grants this node only `notifier`, so a validator checking imports against the graph may reject the component until the graph is updated.
- The query string sends the digest overview to `metadata.internal.example`. Overviews are model-written from untrusted feed content, so that host receives that text on every run.

